#include <chrono>
#include <iomanip>
#include <iostream>

#include <noarr/traversers.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "covariance.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

struct tuning {
	// data: i (observations) x j (features)
	DEFINE_PROTO_STRUCT(data_layout, j_vec ^ i_vec);
	// covariance: j (feature row) x k (feature column)
	DEFINE_PROTO_STRUCT(cov_layout, k_vec ^ j_vec);
	// mean: j (features)
	DEFINE_PROTO_STRUCT(mean_layout, j_vec);
} tuning;

// initialization function
// data: i x j
void init_array(num_t &float_n, auto data) {
	using namespace noarr;

	// number of observations and features
	auto n = data | get_length<'i'>();
	auto m = data | get_length<'j'>();

	float_n = static_cast<num_t>(n);

	traverser(data).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		data[state] = static_cast<num_t>(i * j) / static_cast<num_t>(m);
	});
}

// computation kernel
// data: i x j
// cov:  j x k  (both j and k range over features 0..m-1)
// mean: j
[[gnu::flatten, gnu::noinline]]
void kernel_covariance(num_t float_n, auto data, auto cov, auto mean) {
	using namespace noarr;

#pragma scop
	// mean[j] = sum_i data[i][j] / float_n;
	traverser(data, mean).template for_dims<'j'>([=](auto trav) {
		// trav has 'j' fixed (one feature column)
		auto col_state = trav.state(); // contains only 'j'

		mean[col_state] = num_t(0);

		trav.for_each([=](auto state) {
			// state has 'i' and 'j'
			mean[col_state] += data[state];
		});

		mean[col_state] /= float_n;
	});

	// center the data: data[i][j] -= mean[j];
	traverser(data, mean).for_each([=](auto state) {
		data[state] -= mean[state]; // mean ignores the 'i' index in the state
	});

	// covariance:
	// for i in 0..M-1
	//   for j in i..M-1
	//     cov[i][j] = sum_k data[k][i] * data[k][j] / (float_n - 1);
	//     cov[j][i] = cov[i][j];
	traverser(cov).for_each([&](auto cov_state) {
		auto row = get_index<'j'>(cov_state); // first feature index
		auto col = get_index<'k'>(cov_state); // second feature index

		// only compute upper triangle (including diagonal)
		if (col < row)
			return;

		num_t sum = num_t(0);

		// sum over all observations in dimension 'i'
		traverser(data).template for_dims<'i'>([&](auto data_trav) {
			auto obs_state = data_trav.state(); // contains only 'i'
			auto obs = get_index<'i'>(obs_state);

			auto state_row = noarr::idx<'i', 'j'>(obs, row);
			auto state_col = noarr::idx<'i', 'j'>(obs, col);

			sum += data[state_row] * data[state_col];
		});

		num_t val = sum / (float_n - num_t(1.0));

		// write symmetric entries
		cov[cov_state] = val;

		auto cov_sym_state = noarr::idx<'j', 'k'>(col, row);
		cov[cov_sym_state] = val;
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N; // number of observations
	std::size_t m = M; // number of features

	// input parameter
	num_t float_n;

	// set lengths for all potentially used dimensions
	auto set_lengths = noarr::set_length<'i'>(n)
	                 ^ noarr::set_length<'j'>(m)
	                 ^ noarr::set_length<'k'>(m);

	// data structures
	auto data = noarr::bag(noarr::scalar<num_t>() ^ tuning.data_layout ^ set_lengths);
	auto cov  = noarr::bag(noarr::scalar<num_t>() ^ tuning.cov_layout  ^ set_lengths);
	auto mean = noarr::bag(noarr::scalar<num_t>() ^ tuning.mean_layout ^ set_lengths);

	// initialize data
	init_array(float_n, data.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_covariance(float_n, data.get_ref(), cov.get_ref(), mean.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (and prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, cov.get_ref() ^ noarr::hoist<'j'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}

#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include <noarr/traversers.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "covariance.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto n_vec = noarr::vector<'n'>(); // observation index (0..N-1)
constexpr auto m_vec = noarr::vector<'m'>(); // feature index (0..M-1)

constexpr auto i_vec = noarr::vector<'i'>(); // row index in covariance
constexpr auto j_vec = noarr::vector<'j'>(); // column index in covariance

// layouts
constexpr auto data_layout = m_vec ^ n_vec;  // data: n x m
constexpr auto cov_layout  = j_vec ^ i_vec;  // cov : i x j (both size m)
constexpr auto mean_layout = m_vec;          // mean: m


// Array initialization.
// data: n x m (observations x features)
void init_array(std::size_t n, std::size_t m,
                num_t &float_n,
                auto data) {
	using namespace noarr;

	float_n = static_cast<num_t>(n);

	traverser(data).for_each([=](auto state) {
		auto [ni, mj] = get_indices<'n', 'm'>(state);
		data[state] = static_cast<num_t>(ni * mj) / static_cast<num_t>(m);
	});
}


// Main computational kernel.
// Computes the covariance matrix of the centered data.
[[gnu::flatten, gnu::noinline]]
void kernel_covariance(std::size_t n, std::size_t m,
                       num_t float_n,
                       auto data,
                       auto cov,
                       auto mean) {
	using namespace noarr;
	(void)n;
	(void)m;

	#pragma scop

	// ------------------------------------------------------------------
	// 1) Compute mean of each feature (column)
	//    mean[j] = (1/float_n) * sum_i data[i][j]
	// ------------------------------------------------------------------
	traverser(data, mean).template for_dims<'m'>([=](auto trav_m) {
		// trav_m has 'm' fixed (one feature j), 'n' varies over observations

		// mean[j] = 0.0;
		mean[trav_m] = num_t(0.0);

		// mean[j] += data[i][j] over all i
		trav_m.for_each([=](auto state) {
			mean[trav_m] += data[state];
		});

		// mean[j] /= float_n;
		mean[trav_m] /= float_n;
	});

	// ------------------------------------------------------------------
	// 2) Center the data by subtracting the mean from each column
	//    data[i][j] -= mean[j]
	// ------------------------------------------------------------------
	traverser(data, mean).for_each([=](auto state) {
		// state has ('n','m'); mean ignores 'n' and uses only 'm'
		data[state] -= mean[state];
	});

	// ------------------------------------------------------------------
	// 3) Compute covariance matrix
	//    for i in [0, M)
	//      for j in [i, M)
	//        cov[i][j] = sum_k data[k][i] * data[k][j] / (float_n - 1)
	//        cov[j][i] = cov[i][j]
	// We implement triangular (j >= i) region with a rectangular traversal
	// and an early return for j < i.
	// ------------------------------------------------------------------
	traverser(cov).template for_dims<'i'>([=](auto cov_i_trav) {
		// cov_i_trav has 'i' fixed, 'j' varying
		auto i_idx = get_index<'i'>(cov_i_trav.state());

		cov_i_trav.for_each([=](auto cov_state) {
			auto j_idx = get_index<'j'>(cov_state);

			// enforce j >= i to match original triangular loops
			if (j_idx < i_idx)
				return;

			// cov[i][j] = 0.0;
			cov[cov_state] = num_t(0.0);

			// accumulate over all observations k (dimension 'n')
			traverser(data).template for_dims<'n'>([=](auto data_n_trav) {
				auto k_idx = get_index<'n'>(data_n_trav.state());

				// data[k][i] and data[k][j] (columns i and j)
				auto data_state_i = noarr::idx<'n', 'm'>(k_idx, i_idx);
				auto data_state_j = noarr::idx<'n', 'm'>(k_idx, j_idx);

				cov[cov_state] += data[data_state_i] * data[data_state_j];
			});

			// cov[i][j] /= (float_n - 1.0);
			cov[cov_state] /= (float_n - num_t(1.0));

			// cov[j][i] = cov[i][j];
			cov[noarr::idx<'i', 'j'>(j_idx, i_idx)] = cov[cov_state];
		});
	});

	#pragma endscop
}

} // namespace


int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N; // number of observations
	std::size_t m = M; // number of features

	// scalar parameter
	num_t float_n;

	// set lengths per dimension
	auto data_lengths = noarr::set_length<'n'>(n) ^ noarr::set_length<'m'>(m);
	auto cov_lengths  = noarr::set_length<'i'>(m) ^ noarr::set_length<'j'>(m);
	auto mean_lengths = noarr::set_length<'m'>(m);

	// allocate bags
	auto data = noarr::bag(noarr::scalar<num_t>() ^ data_layout ^ data_lengths);
	auto cov  = noarr::bag(noarr::scalar<num_t>() ^ cov_layout  ^ cov_lengths);
	auto mean = noarr::bag(noarr::scalar<num_t>() ^ mean_layout ^ mean_lengths);

	// initialize data
	init_array(n, m, float_n, data.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_covariance(n, m, float_n,
	                  data.get_ref(), cov.get_ref(), mean.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// optionally print the covariance matrix (to stderr)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, cov.get_ref() ^ noarr::hoist<'i'>());
	}

	// print execution time (to stdout)
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}

