#include "covariance.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto n_vec = noarr::vector<'n'>();
constexpr auto m_vec = noarr::vector<'m'>();
constexpr auto p_vec = noarr::vector<'p'>();
constexpr auto q_vec = noarr::vector<'q'>();

struct tuning {
	// data: n x m
	DEFINE_PROTO_STRUCT(data_layout, m_vec ^ n_vec);
	// cov: p x q (both of size m)
	DEFINE_PROTO_STRUCT(cov_layout, q_vec ^ p_vec);
	// mean: m
	DEFINE_PROTO_STRUCT(mean_layout, m_vec);
} tuning;

// initialization function
void init_array(num_t &float_n, auto data) {
	using namespace noarr;

	// float_n = (num_t)n
	float_n = static_cast<num_t>(data | get_length<'n'>());

	// data: n x m
	traverser(data).for_each([=](auto state) {
		auto [i, j] = get_indices<'n', 'm'>(state);
		data[state] = static_cast<num_t>(i * j) /
		              static_cast<num_t>(data | get_length<'m'>());
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_covariance(num_t float_n, auto data, auto cov, auto mean) {
	using namespace noarr;

	// Step 1: compute mean of each column (feature)
	// mean[j] = (1 / float_n) * sum_i data[i][j]
	traverser(data, mean).template for_dims<'m'>([=](auto trav_m) {
		// fixed column index
		auto s_m = trav_m.state();

		// mean[j] = 0.0
		mean[s_m] = static_cast<num_t>(0);

		// accumulate over all rows (dimension 'n')
		trav_m.for_each([=](auto state) {
			mean[state] += data[state];
		});

		// divide by float_n
		mean[s_m] /= float_n;
	});

	// Step 2: center the data
	// data[i][j] -= mean[j]
	traverser(data, mean).template for_dims<'n'>([=](auto trav_n) {
		trav_n.for_each([=](auto state) {
			data[state] -= mean[state];
		});
	});

	// Step 3: compute covariance matrix
	// cov[i][j] = sum_k data[k][i] * data[k][j] / (float_n - 1)
	// then symmetrize: cov[j][i] = cov[i][j]

	const std::size_t m_len = cov | get_length<'q'>(); // size of feature dimension

	traverser(cov).template for_dims<'p'>([=](auto trav_p) {
		// fixed row index in covariance matrix
		auto s_p = trav_p.state();
		const std::size_t i_idx = get_index<'p'>(s_p);

		// restrict 'q' to j in [i_idx, m_len)
		auto trav_upper = trav_p.order(noarr::slice<'q'>(i_idx, m_len - i_idx));

		trav_upper.for_each([=](auto state_pq) {
			const std::size_t j_idx = get_index<'q'>(state_pq);

			// cov[i][j] = 0.0
			cov[state_pq] = static_cast<num_t>(0);

			// create views of data for columns i and j
			auto data_ref = data.get_ref();
			auto data_i = data_ref ^ noarr::fix<'m'>(i_idx);
			auto data_j = data_ref ^ noarr::fix<'m'>(j_idx);

			// accumulate over all rows (dimension 'n')
			traverser(data_i, data_j).for_each([=](auto state_n) {
				cov[state_pq] += data_i[state_n] * data_j[state_n];
			});

			// divide by (float_n - 1.0)
			cov[state_pq] /= (float_n - static_cast<num_t>(1.0));

			// symmetrize: cov[j][i] = cov[i][j]
			auto state_qp = noarr::idx<'p', 'q'>(j_idx, i_idx);
			cov[state_qp] = cov[state_pq];
		});
	});
}

