#include <chrono>
#include <iomanip>
#include <iostream>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "covariance.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto r_vec = noarr::vector<'r'>(); // rows (N)
constexpr auto c_vec = noarr::vector<'c'>(); // columns (M), first index of cov and mean
constexpr auto d_vec = noarr::vector<'d'>(); // second index of cov (M)

// Layout tuning: choose concrete memory layouts
struct tuning {
	// data: N x M, row-major: data[r][c]
	DEFINE_PROTO_STRUCT(data_layout, c_vec ^ r_vec);

	// cov: M x M, row-major: cov[c][d]
	DEFINE_PROTO_STRUCT(cov_layout, d_vec ^ c_vec);

	// mean: M
	DEFINE_PROTO_STRUCT(mean_layout, c_vec);
} tuning;


// initialization function
// data: r x c
void init_array(num_t &float_n, auto data) {
	using namespace noarr;

	// lengths of the two dimensions
	auto n_len = data | get_length<'r'>(); // N
	auto m_len = data | get_length<'c'>(); // M

	float_n = static_cast<num_t>(n_len);

	// for (i = 0; i < N; i++)
	//   for (j = 0; j < M; j++)
	//     data[i][j] = ((DATA_TYPE) i*j) / M;
	traverser(data).for_each([&](auto state) {
		auto [r, c] = get_indices<'r', 'c'>(state);
		data[state] = static_cast<num_t>(r * c) / static_cast<num_t>(m_len);
	});
}


// computation kernel
// data: r x c
// cov:  c x d  (both extents equal to M)
// mean: c
[[gnu::flatten, gnu::noinline]]
void kernel_covariance(num_t float_n, auto data, auto cov, auto mean) {
	using namespace noarr;

#pragma scop
	// ---------------------------------------------------------------------
	// 1) Compute the mean of each column of `data`
	//
	// Original:
	// for (j = 0; j < M; j++) {
	//   mean[j] = 0.0;
	//   for (i = 0; i < N; i++)
	//     mean[j] += data[i][j];
	//   mean[j] /= float_n;
	// }
	// ---------------------------------------------------------------------
	traverser(mean, data).template for_dims<'c'>([&](auto trav_c) {
		// trav_c has 'c' fixed, iterates remaining dimension 'r'
		auto s_c = trav_c.state(); // state with just 'c'

		// mean[c] = 0.0;
		mean[s_c] = static_cast<num_t>(0.0);

		// accumulate over all rows r
		trav_c.for_each([&](auto state) {
			// state has 'r' and fixed 'c'
			mean[s_c] += data[state];
		});

		// mean[c] /= float_n;
		mean[s_c] /= float_n;
	});

	// ---------------------------------------------------------------------
	// 2) Center the data matrix: data[r][c] -= mean[c]
	//
	// Original:
	// for (i = 0; i < N; i++)
	//   for (j = 0; j < M; j++)
	//     data[i][j] -= mean[j];
	// ---------------------------------------------------------------------
	traverser(data, mean).for_each([&](auto state) {
		// state has 'r' and 'c'
		data[state] -= mean[state]; // mean ignores 'r', uses 'c'
	});

	// ---------------------------------------------------------------------
	// 3) Compute the covariance matrix
	//
	// Original:
	// for (i = 0; i < M; i++)
	//   for (j = i; j < M; j++) {
	//     cov[i][j] = 0.0;
	//     for (k = 0; k < N; k++)
	//       cov[i][j] += data[k][i] * data[k][j];
	//     cov[i][j] /= (float_n - 1.0);
	//     cov[j][i] = cov[i][j];
	//   }
	// ---------------------------------------------------------------------
	traverser(cov).template for_dims<'c'>([&](auto trav_c) {
		// trav_c has 'c' fixed, iterates remaining dimension 'd'
		auto s_c = trav_c.state();
		std::size_t ci = get_index<'c'>(s_c); // i in original code

		// total number of columns (M)
		auto m_len = cov | get_length<'d'>();

		// restrict 'd' to the range [ci, m_len)  -> j from i to M-1
		auto trav_upper = trav_c.order(noarr::slice<'d'>(ci, m_len - ci));

		trav_upper.for_each([&](auto state_cd) {
			std::size_t cj = get_index<'d'>(state_cd); // j in original code

			// cov[ci][cj] = 0.0;
			num_t sum = static_cast<num_t>(0.0);

			// views of columns ci and cj of the data matrix
			auto col_i = data ^ noarr::fix<'c'>(ci);
			auto col_j = data ^ noarr::fix<'c'>(cj);

			// sum over all rows r: data[r][ci] * data[r][cj]
			traverser(col_i, col_j).for_each([&](auto s_r) {
				sum += col_i[s_r] * col_j[s_r];
			});

			// cov[ci][cj] = sum / (float_n - 1.0);
			num_t value = sum / (float_n - static_cast<num_t>(1.0));
			cov[state_cd] = value;

			// cov[cj][ci] = cov[ci][cj];  (enforce symmetry)
			auto state_dc = noarr::idx<'c', 'd'>(cj, ci);
			cov[state_dc] = value;
		});
	});
#pragma endscop
}

} // namespace


int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N; // number of rows
	std::size_t m = M; // number of columns

	// scalar parameter
	num_t float_n;

	// set lengths for each structure
	auto data_lengths = noarr::set_length<'r'>(n) ^ noarr::set_length<'c'>(m);
	auto cov_lengths  = noarr::set_length<'c'>(m) ^ noarr::set_length<'d'>(m);
	auto mean_lengths = noarr::set_length<'c'>(m);

	// bags for data structures
	auto data = noarr::bag(noarr::scalar<num_t>() ^ tuning.data_layout ^ data_lengths);
	auto cov  = noarr::bag(noarr::scalar<num_t>() ^ tuning.cov_layout ^ cov_lengths);
	auto mean = noarr::bag(noarr::scalar<num_t>() ^ tuning.mean_layout ^ mean_lengths);

	// initialize arrays
	init_array(float_n, data.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_covariance(float_n, data.get_ref(), cov.get_ref(), mean.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (touch all live-out data to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, cov.get_ref() ^ noarr::hoist<'c'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}

